WITH session_stats AS (SELECT session_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(event_type))) AS event_type_values, SUM(CASE WHEN page = '/product' THEN duration_sec ELSE 0 END) AS product_duration_sec FROM web_events GROUP BY session_id) SELECT s.country, s.customer_id, ss.event_type_values, ss.product_duration_sec FROM sessions s JOIN session_stats ss ON s.id = ss.session_id WHERE ss.product_duration_sec >= 27;
